/* 本段内 R、模式不变 → 精确解 V = V_T + (V0 − V_T)·e^(−Δt/τ) */
state.voltage = vT + (v0 - vT) * Math.exp(-dt / tau);
state.time += dt;
samples.push({time: state.time, voltage: state.voltage});
render();

const xmax = Math.max(0.1, state.time);           // 横轴重缩放：只改屏幕映射
const X = t => 55 + 715 * t / xmax;
const Y = v => 260 - 23.5 * v;                    // 0 V→260，10 V→25
ui.trace.setAttribute('points',
  samples.map(s => X(s.time).toFixed(4) + ',' + Y(s.voltage).toFixed(4)).join(' '));
